"import os

def w(path, text):
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "w") as f:
        f.write(text)

# Domain and simulation parameters (per task spec)
LX, LY, LZ = 9.0, 1.0, 2.0
T_HOT, T_COLD = 315.0, 290.0
DT, END, WRITE = 1.0, 1000.0, 50.0
NX, NY, NZ = 90, 10, 20  # ~10 cells/单位 — 3D resolution

# system/controlDict
w("system/controlDict",
    "FoamFile { format ascii; class dictionary; object controlDict; "
    + 'location "system/controlDict"; }\n'
    + "application     buoyantFoam;\n"
    + "startFrom       latestTime;\n"
    + "startTime       0;\n"
    + "stopAt          endTime;\n"
    + f"endTime         {END};\n"
    + f"deltaT          {DT};\n"
    + "writeControl    runTime;\n"
    + f"writeInterval   {WRITE};\n"
    + "purgeWrite      0;\n"
    + "writeFormat     ascii;\n"
    + "writePrecision  6;\n"
    + "timeFormat      general;\n"
    + "runTimeModifiable true;\n")

# system/fvSchemes
w("system/fvSchemes", """FoamFile { format ascii; class dictionary; object fvSchemes; location "system/fvSchemes"; }
ddtSchemes { default Euler; }
gradSchemes { default Gauss linear; }
divSchemes
{
    default none;
    div(phi,U)  bounded Gauss limitedLinear 0.2;
    div(phi,K)  bounded Gauss limitedLinear 0.2;
    div(phi,h)  bounded Gauss limitedLinear 0.2;
    div(phi,T)  bounded Gauss limitedLinear 0.2;
    div(((rho*nuEff)*dev2(T(grad(U))))) Gauss linear;
}
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
""")

# system/fvSolution
w("system/fvSolution", """FoamFile { format ascii; class dictionary; object fvSolution; location "system/fvSolution"; }
solvers
{
    p_rgh { solver GAMG; tolerance 1e-7; relTol 0.01; smoother DICGaussSeidel; }
    p_rghFinal { solver GAMG; tolerance 1e-7; relTol 0; smoother DICGaussSeidel; }
    "(U|h|k|epsilon|omega)"
    {
        solver PBiCGStab; preconditioner DILU; tolerance 1e-8; relTol 0.1;
    }
    "(U|h|k|epsilon|omega)Final"
    {
        solver PBiCGStab; preconditioner DILU; tolerance 1e-8; relTol 0;
    }
    "(rho|rhoFinal)"
    {
        solver PBiCGStab; preconditioner DILU; tolerance 1e-8; relTol 0;
    }
}
PIMPLE
{
    momentumPredictor no;
    nNonOrthogonalCorrectors 0;
    pRefCell 0;
    pRefValue 0;
}
relaxationFactors { equations { ".*" 1; } }
""")

# system/blockMeshDict
w("system/blockMeshDict",
    "FoamFile { format ascii; class dictionary; object blockMeshDict; "
    + 'location "system/blockMeshDict"; }\n'
    + "convertToMeters 1;\n"
    + "vertices (\n"
    + f"    (0 0 0) ({LX} 0 0) ({LX} {LY} 0) (0 {LY} 0)\n"
    + f"    (0 0 {LZ}) ({LX} 0 {LZ}) ({LX} {LY} {LZ}) (0 {LY} {LZ})\n"
    + ");\n"
    + f"blocks ( hex (0 1 2 3 4 5 6 7) ({NX} {NY} {NZ}) simpleGrading (1 1 1) );\n"
    + "boundary (\n"
    + "    bottom { type wall; faces ((0 1 5 4)); }\n"
    + "    top { type wall; faces ((3 2 6 7)); }\n"
    + "    frontAndBack { type wall; faces ((0 1 2 3) (4 5 6 7)); }\n"
    + "    inlet { type wall; faces ((0 3 7 4)); }\n"
    + "    outlet { type wall; faces ((1 2 6 5)); }\n"
    + ");\n")

# constant/physicalProperties (OF10 heRhoThermo)
w("constant/physicalProperties", """FoamFile { format ascii; class dictionary; object physicalProperties; location "constant/physicalProperties"; }
thermoType
{
    type            heRhoThermo;
    mixture         pureMixture;
